<script lang="ts">
 import Papa from 'papaparse';import { translator } from '$lib/app-i18n';import DataTable from '$lib/components/DataTable.svelte';
 let {data}=$props();let t=$derived(translator(data.lang)),csv=$state(''),filename=$state(''),columns=$state<string[]>([]),mapping=$state<Record<string,string>>({}),rows=$state<Record<string,any>[]>([]),batch=$state(''),message=$state(''),busy=$state(false),committed=$state(false);
 const fields=['lot_code','vessel_code','name','grape','vintage','quantity_l','capacity_l','cost_per_l'];
 async function file(event:Event){const selected=(event.currentTarget as HTMLInputElement).files?.[0];if(!selected)return;csv=await selected.text();filename=selected.name;columns=Papa.parse(csv,{header:true}).meta.fields??[];mapping=Object.fromEntries(fields.map(field=>[field,columns.find(column=>column.toLowerCase()===field)??'']));rows=[];batch='';committed=false;}
 async function preview(){busy=true;try{const res=await fetch('/api/import',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({csv,filename,mapping})});const result=await res.json();if(!res.ok){message=result.message;return;}rows=result.rows;batch=result.id;committed=result.state==='committed';message=committed?t('saved'):'';}finally{busy=false;}}
 async function commit(){busy=true;try{const res=await fetch('/api/import',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({batch_id:batch})});const result=await res.json();if(!res.ok){message=result.message;return;}rows=result.report;committed=true;message=t('saved');}finally{busy=false;}}
</script>
<p class="eyebrow">{data.tenant.name}</p><h1>{t('import')}</h1><section class="card"><label>CSV<input type="file" accept=".csv,text/csv" onchange={file} /></label>{#if columns.length}<form onsubmit={(e)=>{e.preventDefault();preview();}}><div class="mapping">{#each fields as field}<label>{t(field)}<select bind:value={mapping[field]} required={!['grape','cost_per_l'].includes(field)}><option value="">—</option>{#each columns as column}<option value={column}>{column}</option>{/each}</select></label>{/each}</div><button disabled={busy}>{t('preview')}</button></form>{/if}</section>{#if rows.length}<section class="card"><DataTable {rows} columns={committed?['row','status','error']:['row',...fields,'error']} {t} />{#if batch&&!committed}<button onclick={commit} disabled={busy}>{t('commit')}</button>{/if}</section>{/if}<p role="status">{message}</p><a href="/app/data">{t('data')}</a>
<style>.mapping{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin:22px 0}button{margin-top:16px}</style>
